<?php
/**
 * Plugin Name: EVSTAR Seed
 * Description: One-time import of the starting content (products, pages, settings, privacy policy) for EVSTAR Core. Deactivate and delete after use.
 * Version:     0.1.0
 * Requires PHP: 8.1
 *
 * Data comes from data.json, generated by `npx tsx scripts/export-wp-seed.ts`
 * in the Next.js repo. Images are uploaded from ./images once (matched by file name).
 *
 * Safe to run more than once:
 *   - products are matched by slug and categories by slug — existing ones are skipped
 *     unless "overwrite" is ticked
 *   - page fields, settings and the privacy policy are only written when empty,
 *     unless "overwrite" is ticked
 */

defined( 'ABSPATH' ) || exit;

add_action( 'admin_menu', function () {
	add_management_page( 'EVSTAR Import', 'EVSTAR Import', 'manage_options', 'evstar-seed', 'evstar_seed_page' );
} );

function evstar_seed_page(): void {
	$log = null;
	if ( isset( $_POST['evstar_seed'] ) && check_admin_referer( 'evstar_seed' ) ) {
		$log = evstar_seed_run( ! empty( $_POST['overwrite'] ) );
	}
	$ready = function_exists( 'evstar_page_id' ) && function_exists( 'update_field' );
	?>
	<div class="wrap">
		<h1>EVSTAR Import</h1>
		<?php if ( ! $ready ) : ?>
			<div class="notice notice-error"><p>Activate Secure Custom Fields and EVSTAR Core first.</p></div>
		<?php else : ?>
			<p>Imports the starting products, page content, site settings and privacy policy.
				Portfolio cases are not imported (the mock ones are placeholders).</p>
			<form method="post">
				<?php wp_nonce_field( 'evstar_seed' ); ?>
				<p><label><input type="checkbox" name="overwrite" value="1"> Overwrite content that already exists</label></p>
				<p><button class="button button-primary" name="evstar_seed" value="1">Run import</button></p>
			</form>
		<?php endif; ?>
		<?php if ( $log ) : ?>
			<h2>Result</h2>
			<pre style="background:#fff;padding:12px;max-height:480px;overflow:auto"><?php echo esc_html( implode( "\n", $log ) ); ?></pre>
			<p>When you're happy with the result, deactivate and delete this plugin.</p>
		<?php endif; ?>
	</div>
	<?php
}

/** @return string[] log lines */
function evstar_seed_run( bool $overwrite ): array {
	@set_time_limit( 300 );
	$log  = [];
	$data = json_decode( (string) file_get_contents( __DIR__ . '/data.json' ), true );
	if ( ! is_array( $data ) ) {
		return [ 'data.json is missing or invalid.' ];
	}

	// Writes trigger one revalidation request at the end, not one per field.
	wp_defer_term_counting( true );

	/* Categories --------------------------------------------------------- */
	foreach ( $data['categories'] as $cat ) {
		$term = get_term_by( 'slug', $cat['slug'], 'product_category' );
		if ( ! $term ) {
			$res  = wp_insert_term( $cat['name'], 'product_category', [ 'slug' => $cat['slug'] ] );
			$term = is_wp_error( $res ) ? null : get_term( $res['term_id'], 'product_category' );
		} elseif ( $overwrite ) {
			wp_update_term( $term->term_id, 'product_category', [ 'name' => $cat['name'] ] );
		}
		if ( ! $term ) {
			$log[] = "✗ category {$cat['slug']}";
			continue;
		}
		$target = 'product_category_' . $term->term_id;
		foreach ( $cat['fields'] as $name => $value ) {
			evstar_seed_field( 'product_category', $name, $value, $target, $overwrite );
		}
		$log[] = "✓ category {$cat['slug']}";
	}

	/* Products ----------------------------------------------------------- */
	$product_ids = [];
	foreach ( $data['products'] as $product ) {
		$existing = get_page_by_path( $product['slug'], OBJECT, 'product' );
		if ( $existing && ! $overwrite ) {
			$product_ids[ $product['slug'] ] = $existing->ID;
			$log[] = "· product {$product['slug']} exists, skipped";
			continue;
		}

		$id = wp_insert_post( [
			'ID'          => $existing->ID ?? 0,
			'post_type'   => 'product',
			'post_status' => 'publish',
			'post_title'  => $product['title'],
			'post_name'   => $product['slug'],
			'menu_order'  => $product['menuOrder'],
		], true );
		if ( is_wp_error( $id ) ) {
			$log[] = "✗ product {$product['slug']}: " . $id->get_error_message();
			continue;
		}
		$product_ids[ $product['slug'] ] = $id;

		wp_set_object_terms( $id, [ $product['category'] ], 'product_category' );
		foreach ( $product['fields'] as $name => $value ) {
			evstar_seed_field( 'product', $name, $value, $id, true );
		}
		if ( $product['image'] ) {
			$media = evstar_seed_image( $product['image'] );
			if ( $media ) {
				set_post_thumbnail( $id, $media );
			}
		}
		$log[] = "✓ product {$product['slug']}";
	}

	/* Pages -------------------------------------------------------------- */
	$groups = [
		'home'      => 'home',
		'products'  => 'products_page',
		'services'  => 'services_page',
		'portfolio' => 'portfolio_page',
		'about'     => 'about_page',
		'quote'     => 'quote_page',
	];
	foreach ( $data['pages'] as $key => $fields ) {
		$page_id = evstar_page_id( $key );
		if ( ! $page_id || empty( $groups[ $key ] ) ) {
			$log[] = "✗ page {$key}: not found";
			continue;
		}
		$fields = evstar_seed_resolve( $fields, $product_ids );
		$wrote  = 0;
		foreach ( $fields as $name => $value ) {
			$wrote += evstar_seed_field( $groups[ $key ], $name, $value, $page_id, $overwrite ) ? 1 : 0;
		}
		$log[] = "✓ page {$key}: {$wrote} fields written";
	}

	/* Privacy policy ----------------------------------------------------- */
	$privacy = evstar_page_id( 'privacy-policy' );
	if ( $privacy ) {
		$current = get_post_field( 'post_content', $privacy );
		// WordPress's default draft contains "privacy-policy-tutorial" — treat it as empty.
		if ( $overwrite || '' === trim( $current ) || str_contains( $current, 'privacy-policy-tutorial' ) ) {
			wp_update_post( [
				'ID'           => $privacy,
				'post_title'   => $data['privacyPolicy']['title'],
				'post_content' => wp_slash( $data['privacyPolicy']['content'] ),
			] );
			$log[] = '✓ privacy policy';
		} else {
			$log[] = '· privacy policy has content, skipped';
		}
	}

	/* Settings ----------------------------------------------------------- */
	$wrote = 0;
	foreach ( $data['settings'] as $name => $value ) {
		$wrote += evstar_seed_field( 'settings', $name, $value, 'option', $overwrite ) ? 1 : 0;
	}
	$log[] = "✓ settings: {$wrote} fields written";

	wp_defer_term_counting( false );

	if ( function_exists( 'evstar_queue_revalidate' ) ) {
		evstar_queue_revalidate( [ 'home', 'products', 'services', 'portfolio', 'about', 'quote', 'privacy-policy', 'settings' ] );
	}

	return $log;
}

/**
 * Write one top-level field by key. Nested values may use field names —
 * SCF resolves those within the parent field.
 */
function evstar_seed_field( string $group, string $name, $value, $target, bool $overwrite ): bool {
	$key = "field_evstar_{$group}_{$name}";
	if ( ! acf_get_field( $key ) ) {
		return false;
	}
	if ( ! $overwrite ) {
		$current = get_field( $key, $target, false );
		if ( ! evstar_seed_is_empty( $current ) ) {
			return false;
		}
	}
	return (bool) update_field( $key, $value, $target );
}

function evstar_seed_is_empty( $value ): bool {
	if ( is_array( $value ) ) {
		foreach ( $value as $v ) {
			if ( ! evstar_seed_is_empty( $v ) ) {
				return false;
			}
		}
		return true;
	}
	return null === $value || '' === $value || false === $value;
}

/**
 * Replace references in page data:
 *   "product": "adc002"            → product post ID
 *   { "file": "x.png", "alt": … }  → attachment ID
 *   null                           → "" (SCF clears the field)
 */
function evstar_seed_resolve( $value, array $product_ids, ?string $name = null ) {
	if ( is_array( $value ) ) {
		if ( isset( $value['file'] ) && array_key_exists( 'alt', $value ) ) {
			return evstar_seed_image( $value ) ?: '';
		}
		$out = [];
		foreach ( $value as $k => $v ) {
			$out[ $k ] = evstar_seed_resolve( $v, $product_ids, is_string( $k ) ? $k : $name );
		}
		return $out;
	}
	if ( 'product' === $name && is_string( $value ) ) {
		return $product_ids[ $value ] ?? '';
	}
	return $value ?? '';
}

/** Upload ./images/<file> once; later calls reuse the attachment. */
function evstar_seed_image( array $image ): int {
	$existing = get_posts( [
		'post_type'      => 'attachment',
		'post_status'    => 'inherit',
		'meta_key'       => '_evstar_seed_file',
		'meta_value'     => $image['file'],
		'fields'         => 'ids',
		'posts_per_page' => 1,
	] );
	if ( $existing ) {
		return (int) $existing[0];
	}

	$source = __DIR__ . '/images/' . basename( $image['file'] );
	if ( ! is_readable( $source ) ) {
		return 0;
	}

	require_once ABSPATH . 'wp-admin/includes/file.php';
	require_once ABSPATH . 'wp-admin/includes/media.php';
	require_once ABSPATH . 'wp-admin/includes/image.php';

	$tmp = wp_tempnam( $image['file'] );
	copy( $source, $tmp );
	$id = media_handle_sideload( [ 'name' => basename( $image['file'] ), 'tmp_name' => $tmp ], 0 );
	if ( is_wp_error( $id ) ) {
		@unlink( $tmp );
		return 0;
	}
	update_post_meta( $id, '_wp_attachment_image_alt', $image['alt'] );
	update_post_meta( $id, '_evstar_seed_file', $image['file'] );
	return (int) $id;
}
